export async function seed(db: Kysely<any>): Promise<void> {
  console.log(`Seeding ${ACTIVITIES_DATA.length} ws_entity_material_activities...`)

  for (const activity of ACTIVITIES_DATA) {
    await db
      .insertInto('ws_entity_material_activities')
      .values({
        id: activity.id,
        activity_id: activity.activity_id,
        entity_id: activity.entity_id,
        material_id: activity.material_id,
        min: activity.min,
        max: activity.max,
        consumption_rate: activity.consumption_rate,
        tax: activity.tax,
        retailer_price: activity.retailer_price,
      })
      .onDuplicateKeyUpdate({
        min: activity.min,
        max: activity.max,
        consumption_rate: activity.consumption_rate,
        tax: activity.tax,
        retailer_price: activity.retailer_price,
      })
      .execute()
  }

  console.log(`✅ Successfully seeded ${ACTIVITIES_DATA.length} ws_entity_material_activities`)
}
